    def test_sweep_withholds_unreadable_sidecar_body(
        self, engaged: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        """#88R36-5: an unreadable body withholds instead of deleting blind."""
        pid, birth = _dead_pid_with_birth()
