    def test_mark_consumed_eperm_renames_via_unlink(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        sidecar = tmp_path / "probe-aaaaaaaa-0-bead1234.json"
