from pkcs11_check.core import call_counters

call_counters.record_call("C_Digest")
info = call_counters.registration_info()
assert info is not None
sys.stderr.write(f"ENTRY-DURABLE sidecar={info['sidecar_path']}\\n")
sys.stderr.flush()
