        deltas = [
            rec for rec in second["cache_records"].get("a.py", []) if rec.get("recovered_keys")
        ]
        assert len(deltas) == 0, "the retry heal holds -- no delta publishes"
        assert tmp.exists(), "unpublished returns never bind on a delta"

